WITH latest AS (SELECT *, RANK() OVER (PARTITION BY method ORDER BY paid_at) AS latest_rank FROM payments QUALIFY latest_rank = 1) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, status, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN method = 'bank_transfer' THEN 1 END), 0), 2) AS amount_per_bank_transfer, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN method = 'promptpay' THEN 1 END), 0), 2) AS amount_per_promptpay FROM latest GROUP BY DATE_TRUNC('MONTH', paid_at), status HAVING amount_per_bank_transfer > 0 ORDER BY status DESC
